#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Records the parked-mode test captures (see the exit-time PR): every take is
# raw CU8 I/Q at the decoder's rate, checked by replaying it through openstint.

SAMPLE_RATE=2500000 # openstint_rtlsdr: 1.25 Msym/s, 2 samples per symbol
CENTER_FREQ=5000000

# record_take NAME SECONDS "SEC|cue" ... records NAME-NN.cu8, shows the cues at
# their second, replays it through the decoder and keeps or redoes it.
record_take() {
  local name="$1" secs="$2"; shift 2
  local n=1 file
  while [[ -e "$OUT_DIR/$(printf '%s-%02d.cu8' "$name" "$n")" ]]; do n=$((n + 1)); done
  file="$OUT_DIR/$(printf '%s-%02d.cu8' "$name" "$n")"
  while true; do
    pause "Take $(basename "$file"): press Enter to start recording"
    local -a dflag=()
    [[ "$DONGLE" == "v3" ]] && dflag=(-D 2)
    rtl_sdr -f "$CENTER_FREQ" -s "$SAMPLE_RATE" -g "$GAIN" "${dflag[@]}" \
      -n $((secs * SAMPLE_RATE)) "$file" >"$OUT_DIR/rtl_sdr.log" 2>&1 &
    local pid=$! t=0 cue
    for cue in "$@"; do
      while (( t < ${cue%%|*} )); do sleep 1; t=$((t + 1)); printf '  %s%ss%s\n' "$DIM" "$t" "$RESET"; done
      printf '  %s%s>>> %s%s\n' "$BOLD" "$YELLOW" "${cue#*|}" "$RESET"
    done
    while kill -0 "$pid" 2>/dev/null; do sleep 1; t=$((t + 1)); printf '  %s%ss%s\n' "$DIM" "$t" "$RESET"; done
    if ! wait "$pid" || [[ ! -s "$file" ]]; then
      warn "rtl_sdr failed:"; tail -n 5 "$OUT_DIR/rtl_sdr.log" | sed 's/^/    /'
      rm -f "$file"; continue
    fi
    say "Recorded $(basename "$file") ($(( $(stat -c %s "$file") / 1000000 )) MB). Decoding it:"
    note "P <ms> <system> <id> <rssi> <hits> <duration us> <snr>"
    "$OPENSTINT_BIN" -c "$file" 2>/dev/null | grep '^P' | sed 's/^/    /' || warn "no passing decoded"
    if confirm "Keep this take?"; then return 0; fi
    rm -f "$file"
  done
}

# takes NAME SECONDS COUNT "SEC|cue" ...: COUNT takes of one scenario
takes() {
  local name="$1" secs="$2" count="$3" i; shift 3
  for ((i = 1; i <= count; i++)); do
    say ""; say "${BOLD}Take $i of $count${RESET}"
    record_take "$name" "$secs" "$@"
  done
}

run_wizard() {

TOTAL_STAGES=10
OUT_DIR="${OUT_DIR:-$HOME/parked-captures}"
mkdir -p "$OUT_DIR"
ENV_FILE="$OUT_DIR/wizard.env"

banner "OpenStint parked-mode test captures"

stage "Tools"
say "Recordings go to $OUT_DIR (change with OUT_DIR=... before running)."
if ! command -v rtl_sdr >/dev/null 2>&1; then
  warn "rtl_sdr is not installed."
  step "RTL-SDR Blog V4: build the rtl-sdr-blog driver (github.com/rtlsdrblog/rtl-sdr-blog);"
  step "the Debian package does not tune a V4 right."
  step "Older dongles: sudo apt install rtl-sdr"
  pause "Install it in another shell, then press Enter"
  command -v rtl_sdr >/dev/null 2>&1 || { warn "still no rtl_sdr, stopping"; exit 1; }
fi
say "rtl_sdr: $(command -v rtl_sdr)"
guess=$(command -v openstint_rtlsdr || ls "$HOME"/openstint/build/src/openstint_rtlsdr "$HOME"/openstint/src/openstint_rtlsdr 2>/dev/null | head -n1 || true)
[[ -z "$(_existing OPENSTINT_BIN || true)" && -n "$guess" ]] && write_env OPENSTINT_BIN "$guess"
ask OPENSTINT_BIN "Path to openstint_rtlsdr (built from the exit-time branch, for the check):"
[[ -x "$OPENSTINT_BIN" ]] || { warn "$OPENSTINT_BIN is not executable, stopping"; exit 1; }
write_env OPENSTINT_BIN "$OPENSTINT_BIN"
pause

stage "Radio"
say "The dongle can only be used by one program, so the decoder service has to stop."
if systemctl is-active --quiet openstint 2>/dev/null; then
  if confirm "Stop the openstint service now (sudo systemctl stop openstint)?"; then
    sudo systemctl stop openstint; RESTART_SERVICE=1
  else
    warn "rtl_sdr will fail while the service holds the dongle"
  fi
fi
say "Gain must match what the decoder runs with, see OPENSTINT_ARGS in /etc/openstint.conf:"
note "$(grep -h OPENSTINT_ARGS /etc/openstint.conf 2>/dev/null || echo 'no /etc/openstint.conf, check your service file')"
ask GAIN "Gain in dB (the -g value):"
write_env GAIN "$GAIN"
say "RTL-SDR Blog V4 receives 5 MHz natively, older dongles need direct sampling (-D 2)."
ask DONGLE "Dongle: v4 or v3 (v3 = any non-V4)?"
[[ "$DONGLE" == "v4" || "$DONGLE" == "v3" ]] || { warn "answer v4 or v3"; exit 1; }
write_env DONGLE "$DONGLE"
pause

stage "Test recording"
say "A 3 s recording with nothing on the loop, to check the radio works."
say "Expect no P line; then delete it (answer N)."
record_take test 3

stage "Reference pass (normal drive-through)"
say "Transponder flat, as in a race. Car about 2 m before the loop."
say "At the cue, drive across the loop at normal speed and stop 2 m behind it."
takes pass 6 3 "2|DRIVE across the loop now"

stage "Parked in front of the loop, then drives across  (case a)"
say "Transponder flat. Park the car about 30 cm BEFORE the loop, so it is"
say "received but not yet over the wire. Place it there before you start."
say "At the cue drive across the loop at normal speed."
note "Expect one P line with a normal pass duration (not 0)."
takes parked_front 9 3 "0|car stays still" "5|DRIVE across the loop now"

stage "Parked on top of the loop, flat transponder  (case b)"
say "Transponder flat. Park the car centered between the loop wires."
say "At the cue drive off forward, across the exit wire."
note "Expect one P line, duration 0, timed at the exit wire."
takes parked_on 9 3 "0|car stays still" "5|DRIVE off now"

stage "Parked on top of the loop, upright transponder  (case b, dips)"
say "Mount the transponder upright, its plane facing the direction of travel."
say "Park centered between the loop wires; at the cue drive off forward."
note "Expect one P line, duration 0."
takes parked_on_ver 9 3 "0|car stays still" "5|DRIVE off now"

stage "Parked at the edge of the field  (case c)"
say "Transponder flat again. Park where the signal is weak, about 50 cm to"
say "the side of the loop or further away, but still received."
say "At the cue drive AWAY from the loop, without crossing a wire."
note "Expect one P line, duration 0, or none if the car was out of range."
takes parked_far 9 3 "0|car stays still" "5|DRIVE away now"

stage "Slow crawl, no stop (must NOT count as parked)"
say "Car about 1 m before the loop. At the cue push it slowly across,"
say "taking 2-3 s over the loop, without stopping, until 1 m behind it."
note "Expect a normal pass at the middle of the crawl."
takes crawl 9 3 "1|PUSH slowly across now" "6|should be past the loop by now"

stage "Crawl in, stop on the loop, drive off"
say "Car about 1 m before the loop. At the first cue crawl slowly onto the"
say "loop and stop centered on it; at the second cue drive off forward."
note "Expect one P line, duration 0, at the drive-off."
takes arrive_park 12 3 "1|CRAWL onto the loop and stop" "7|DRIVE off now"

stage "Pack up"
rm -f "$OUT_DIR/rtl_sdr.log"
ls -1 "$OUT_DIR"/*.cu8 2>/dev/null | sed 's/^/    /'
tar -C "$(dirname "$OUT_DIR")" -czf "$OUT_DIR.tgz" "$(basename "$OUT_DIR")"
say "Packed: $OUT_DIR.tgz ($(( $(stat -c %s "$OUT_DIR.tgz") / 1000000 )) MB)"
say "Copy it off the Pi, e.g. from your PC:"
note "scp pi@<pi-address>:$OUT_DIR.tgz ."
if [[ "${RESTART_SERVICE:-0}" == 1 ]] && confirm "Start the openstint service again?"; then
  sudo systemctl start openstint
fi
pause

finish
}

run_wizard "$@"; exit
